import { Contract } from '@tevm/contract';
import { Address, Hex, EthjsAddress } from '@tevm/utils';

/**
 * Type of predeploy contract for tevm
 */
type Predeploy<TName extends string, THumanReadableAbi extends readonly string[]> = {
    readonly contract: Contract<TName, THumanReadableAbi, Address, Hex, Hex>;
    readonly predeploy: () => {
        address: EthjsAddress;
    };
};

/**
 * Defines a predeploy contract to use in the tevm vm
 * @example
 * ```ts
 * import { definePredeploy } from 'tevm/predeploys'
 * import { createMemoryClient } from 'tevm/vm'
 * import { createContract } from 'tevm/contract'
 *
 * const predeploy = definePredeploy(
 *   createContract({
 *     name: 'PredeployExample',
 *     humanReadableAbi: ['function foo() external pure returns (uint256)'],
 *     bytecode: '0x608060405234801561001057600080fd5b5061012f806100206000396000f3fe608060405260043610610041576000357c0100',
 *     deployedBytecode: '0x608060405260043610610041576000357c010000',
 *   }).withAddress(`0x${'23'.repeat(20)}`),
 * )
 *
 * const vm = createMemoryClient({
 *  customPredeploys: [predeploy],
 * })
 * ```
 */
type DefinePredeployFn = <TName extends string, THumanReadableAbi extends readonly string[]>(contract: Contract<TName, THumanReadableAbi, Address, Hex, Hex>) => Predeploy<TName, THumanReadableAbi>;

/**
 * Defines a predeploy contract to use in the tevm vm
 * @type {import('./DefinePredeployFn.js').DefinePredeployFn}
 * @example
 * ```ts
 * import { definePredeploy } from 'tevm/predeploys'
 * import { createMemoryClient } from 'tevm/vm'
 * import { createContract } from 'tevm/contract'
 *
 * const predeploy = definePredeploy(
 *   createContract({
 *     name: 'PredeployExample',
 *     humanReadableAbi: ['function foo() external pure returns (uint256)'],
 *     bytecode: '0x608060405234801561001057600080fd5b5061012f806100206000396000f3fe608060405260043610610041576000357c0100',
 *     deployedBytecode: '0x608060405260043610610041576000357c010000',
 *   }).withAddress(`0x${'23'.repeat(20)}`),
 * )
 *
 * const vm = createMemoryClient({
 *  customPredeploys: [predeploy],
 * })
 * ```
 */
declare const definePredeploy: DefinePredeployFn;

export { type DefinePredeployFn, type Predeploy, definePredeploy };
